def next_smallest_palindrome(number: int) -> int:
    s = str(number)
    length = len(s)
    if set(s) == {'9'}:
        # All 9s case: next palindrome is 1 followed by zeros and ending with 1
        return int('1' + ('0' * (length - 1)) + '1')

    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[-2::-1])
        else:
            return int(left + left[::-1])

    odd = (length % 2 != 0)
    left_half_len = (length + 1) // 2
    left_half = s[:left_half_len]

    palindrome = make_palindrome(left_half, odd)

    if palindrome > number:
        return palindrome

    # If palindrome is not greater, increment the left half and rebuild
    left_int = int(left_half) + 1
    left_half_new = str(left_int)
    # If length increases (e.g. 99 + 1 = 100), handle separately
    if len(left_half_new) > left_half_len:
        # This means the palindrome length increases by 1
        return int('1' + ('0' * (length - 1)) + '1')
    return make_palindrome(left_half_new, odd)



