def find_Max(array: list[int], start: int, end: int) -> int:
    if start == end:
        return array[start]
    if array[start] < array[end]:
        return array[end]
    mid = (start + end) // 2
    if array[mid] > array[start]:
        return find_Max(array, mid, end)
    elif array[mid] < array[start]:
        return find_Max(array, start, mid)
    else:
        # array[mid] == array[start], fallback to linear search to avoid infinite recursion
        return max(array[start:end+1])



