def capital_words_spaces(text: str) -> str:
    if not text:
        return text
    result = [text[0]]
    for i in range(1, len(text)):
        c = text[i]
        prev = text[i-1]
        if c.isupper() and prev.isalnum() or prev == '_':
            # Check if previous char is a word character (letter, digit, underscore)
            # Insert space only if previous char is word character and c is uppercase
            # Also, do not insert space if previous char is uppercase (to keep acronyms)
            if not (prev.isupper()):
                result.append(' ')
        result.append(c)
    return ''.join(result)



