def substract_elements(minuend: tuple, subtrahend: tuple) -> tuple:
    if not isinstance(minuend, tuple) or not isinstance(subtrahend, tuple):
        raise TypeError("Both minuend and subtrahend must be tuples.")
    if len(minuend) != len(subtrahend):
        raise TypeError("Tuples must be of the same length.")
    result = []
    for m_elem, s_elem in zip(minuend, subtrahend):
        if isinstance(m_elem, tuple):
            if not isinstance(s_elem, tuple):
                raise TypeError("Structure mismatch: minuend element is tuple but subtrahend element is not.")
            result.append(substract_elements(m_elem, s_elem))
        else:
            if isinstance(s_elem, tuple):
                raise TypeError("Structure mismatch: minuend element is not tuple but subtrahend element is tuple.")
            result.append(m_elem - s_elem)
    return tuple(result)



