def lucky_num(n):
    # Start with natural numbers from 1 upwards
    # To ensure enough numbers, start with an estimated range
    # Since lucky numbers are roughly less dense than primes, start with a generous upper bound
    # Increase if needed
    size = max(2 * n * n, 10)  # heuristic initial size
    while True:
        nums = list(range(1, size + 1))
        # Step 1 & 2: Remove even numbers except 1
        nums = [x for x in nums if x == 1 or x % 2 == 1]

        # Step 3 & 4: Apply sieve repeatedly
        idx = 1  # index in nums, 0-based; start from second element as k
        while idx < len(nums):
            k = nums[idx]
            if k > len(nums):
                break
            # Remove every k-th element starting from index k-1 (0-based)
            # Build a new list skipping these positions
            # Elements are 0-based indexed, so remove elements at positions: k-1, 2k-1, 3k-1, ...
            filtered = []
            for i, val in enumerate(nums):
                if (i + 1) % k != 0:
                    filtered.append(val)
            nums = filtered
            idx += 1
            if len(nums) >= n and idx >= n:
                # Once we have at least n elements and processed enough steps, stop
                break

        if len(nums) >= n:
            return nums[:n]
        size *= 2



