def first_even(numbers):
    """
    Locate and return the first even number in the given collection of numbers.

    Parameters:
    numbers (iterable of numbers): A collection (such as a list, tuple, or any iterable) containing numeric values.

    Returns:
    int or float or None: The first even number found in the collection. Returns None if no even number is found.

