def get_total_number_of_sequences(m: int, n: int) -> int:
    if n == 1:
        return m if m >= 1 else 0
    # dp[i][x]: number of sequences of length i+1 ending with x
    dp = [0] * (m + 1)
    for x in range(1, m + 1):
        dp[x] = 1
    for length in range(2, n + 1):
        new_dp = [0] * (m + 1)
        # prefix sums for dp to optimize summation
        prefix = [0] * (m + 2)
        for x in range(1, m + 1):
            prefix[x] = prefix[x - 1] + dp[x]
        for x in range(1, m + 1):
            min_prev = (x + 1) // 2  # prev <= x/2 => prev >= ceil(x/2)
            # sum dp[prev] for prev in [min_prev, m]
            # but prev elements must be <= m, and next >= 2*prev => prev <= x//2
            # So prev <= x//2, so prev in [1, x//2]
            max_prev = x // 2
            if max_prev >= 1:
                new_dp[x] = prefix[max_prev] - prefix[0]
            else:
                new_dp[x] = 0
        dp = new_dp
    return sum(dp[1:])



