def find_Max(arr, low, high):
    # If subarray has one element
    if low == high:
        return arr[low]
    # If subarray is fully sorted (no rotation)
    if arr[low] < arr[high]:
        return arr[high]
    # Binary search for max in rotated sorted subarray
    while low < high:
        mid = (low + high) // 2
        # If mid element is greater than next element, mid is max
        if mid < high and arr[mid] > arr[mid + 1]:
            return arr[mid]
        # If mid element is less than previous element, previous is max
        if mid > low and arr[mid] < arr[mid - 1]:
            return arr[mid - 1]
        # Decide which half to choose
        if arr[mid] >= arr[low]:
            low = mid + 1
        else:
            high = mid - 1
    return arr[low]



