def reverse_Array_Upto_K(sequence, K):
    if K <= 0:
        return sequence
    n = len(sequence)
    k = min(K, n)
    first_part = sequence[:k][::-1]
    rest_part = sequence[k:]
    if isinstance(sequence, str):
        return first_part + rest_part
    elif isinstance(sequence, tuple):
        return tuple(first_part) + rest_part
    else:
        return list(first_part) + list(rest_part)



