import re

def capital_words_spaces(text: str) -> str:
    # Pattern to split the text into sequences of letters and non-letters
    tokens = re.findall(r'[A-Za-z]+|[^A-Za-z]+', text)
    result = []
    for token in tokens:
        if token.isalpha():
            # If token is all letters, check if it is concatenation of multiple capitalized words without spaces
            # Detect if token is multiple capitalized words stuck together:
            # Condition: token starts with uppercase, and inside it there is a lowercase letter followed by uppercase letter,
            # i.e. internal capitalized word boundaries.
            # If so, split token into capitalized words, else keep as is.
            if token[0].isupper() and re.search(r'[a-z][A-Z]', token):
                # Split at positions where uppercase letters start a new word
                parts = re.findall(r'[A-Z][a-z]*|[A-Z]+(?![a-z])', token)
                # Join parts with spaces
                result.append(' '.join(parts))
            else:
                # No splitting needed
                result.append(token)
        else:
            # Non-alpha tokens are added as is
            result.append(token)
    # Join all parts without adding or removing characters except spaces inserted in splits
    # We must preserve original spacing except those splits
    # Join result list:
    # Since non-alpha tokens can include spaces and punctuation, just join directly
    return ''.join(result)



