def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # If all 9's, next palindrome is 10..01 with length+1 digits
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    # Helper to build palindrome from left half
    def build_palindrome(left: str, odd_len: bool) -> int:
        if odd_len:
            return int(left + left[-2::-1])
        else:
            return int(left + left[::-1])

    odd_len = length % 2 != 0
    mid = length // 2

    if odd_len:
        left = s[:mid + 1]
    else:
        left = s[:mid]

    palindrome = build_palindrome(left, odd_len)
    if palindrome > n:
        return palindrome

    # Increment the middle part and rebuild palindrome
    if odd_len:
        # Increment left half as integer
        incremented = str(int(left) + 1)
        # If length changes due to carry, e.g. 999 +1 -> 1000
        if len(incremented) > len(left):
            # This means palindrome length increased by 1
            # So palindrome is 10..01 with length+1 digits
            return int('1' + ('0' * (length - 1)) + '1')
        return build_palindrome(incremented, odd_len)
    else:
        incremented = str(int(left) + 1)
        if len(incremented) > len(left):
            return int('1' + ('0' * (length - 1)) + '1')
        return build_palindrome(incremented, odd_len)



