def get_total_number_of_sequences(m: int, n: int) -> int:
    if n == 1:
        return m
    # dp[i][x]: number of sequences of length i ending with x
    dp = [1] * (m + 1)  # for i=1, dp[x]=1 for x in 1..m
    for _ in range(2, n + 1):
        new_dp = [0] * (m + 1)
        # prefix sums for dp to efficiently sum dp[y] for y >= 2*x
        prefix = [0] * (m + 2)
        for x in range(m, 0, -1):
            prefix[x] = prefix[x + 1] + dp[x]
        for x in range(1, m + 1):
            start = 2 * x
            if start <= m:
                new_dp[x] = prefix[start]
            else:
                new_dp[x] = 0
        dp = new_dp
    return sum(dp[1:])



