def dict_depth(d: dict) -> int:
    def depth(obj) -> int:
        if isinstance(obj, dict):
            if not obj:
                return 1
            return 1 + max((depth(v) for v in obj.values()), default=0)
        elif isinstance(obj, (list, tuple)):
            if not obj:
                return 1
            return 1 + max((depth(e) for e in obj if isinstance(e, (dict, list, tuple))), default=0)
        else:
            return 0
    return depth(d)



