import re

def capital_words_spaces(s: str) -> str:
    # Find the index of the first capital letter ignoring leading spaces
    stripped = s.lstrip(' ')
    if not stripped:
        return s
    first_cap = stripped[0]
    # Find its position in the original string
    first_cap_pos = s.find(first_cap)
    # We'll insert spaces before capitals except if at first_cap_pos
    def repl(m):
        pos = m.start()
        if pos == first_cap_pos:
            return m.group(0)
        return ' ' + m.group(0)
    return re.sub(r'[A-Z]', repl, s)



