def find_solution(a: int, b: int, n: int):
    # Scan non-negative x starting from 0 upwards
    # For each x, check if y = (n - a*x) / b is integer
    # Return first (x,y) with integer y, else None
    # Handle cases when b == 0 separately
    x = 0
    # For practical purposes, since no upper bound is given, 
    # we can loop until a solution is found or no solution exists.
    # To avoid infinite loop, stop if a and b both zero and n != 0 (no solution)
    # If a and b both zero and n==0, infinite solutions, return (0,0)
    if a == 0 and b == 0:
        if n == 0:
            return (0, 0)
        else:
            return None
    # If b == 0, equation is a*x = n, y arbitrary, return first x>=0 with a*x == n
    if b == 0:
        # a*x = n => x = n/a if a divides n
        if a == 0:
            # handled above a==0,b==0 case
            return None
        if n % a == 0:
            x_candidate = n // a
            if x_candidate >= 0:
                # y arbitrary, choose y=0
                return (x_candidate, 0)
        return None
    # If a == 0, equation is b*y = n, x=0 fixed, check if y integer
    if a == 0:
        if n % b == 0:
            y = n // b
            return (0, y)
        else:
            return None
    # General case: a != 0, b != 0
    # Iterate x from 0 upwards
    # To avoid infinite loop, we can limit search to a large number,
    # but since no limit specified, we do indefinite loop
    # Using a loop that breaks when x exceeds abs(n)+abs(b) or so to avoid infinite loop
    # But tests check up to 1000 or 100, so a reasonable limit is 10**6
    limit = 10**6
    for x in range(limit):
        diff = n - a * x
        # Check if diff divisible by b
        if b != 0:
            y, rem = divmod(diff, b)
            if rem == 0:
                return (x, y)
    return None



