def sum_Of_product(n: int) -> int:
    """
    Calculate the sum of the products of binomial coefficients (n choose k) squared for k from 0 to n.

    Specifically, compute the sum:
        sum_{k=0}^n (C(n, k))^2

    where C(n, k) is the binomial coefficient "n choose k".

    Parameters:
    n (int): A non-negative integer representing the upper index of the binomial coefficients.

    Returns:
    int: The sum of the squares of the binomial coefficients from k=0 to k=n.

    Examples:
    >>> sum_Of_product(0)
    1
    >>> sum_Of_product(1)
    2
    >>> sum_Of_product(2)
    6
    >>> sum_Of_product(3)
    20
    """
    return comb(2*n, n)



