def str_to_tuple(s: str) -> tuple[int, ...]:
    if s.strip() != s:
        raise ValueError("Input has leading or trailing whitespace")
    parts = s.split(", ")
    if len(parts) == 0:
        raise ValueError("Input is empty")
    # Check no empty parts and no internal whitespace variations
    for part in parts:
        if part == "" or " " in part.strip("+-0123456789"):
            raise ValueError("Invalid integer or extra whitespace detected")
    try:
        return tuple(int(part) for part in parts)
    except Exception:
