def dif_Square(n: int) -> bool:
    # n = x^2 - y^2 = (x+y)(x-y)
    # For integers x,y, a = x+y and b = x-y must be integers of same parity (so x,y = (a+b)/2, (a-b)/2 integers)
    # So n = a*b with a,b same parity.
    # Unlike previous, a,b can be negative or positive, but a*b = n.
    # a and b must have same parity.

    # Special case n=0: 0 = 0^2 - 0^2
    if n == 0:
        return True

    abs_n = abs(n)
    # Check factor pairs of abs_n
    for a in range(1, int(abs_n**0.5) + 1):
        if abs_n % a == 0:
            b = abs_n // a

            # Check all sign combinations of (a,b) that yield n when multiplied
            for A, B in [(a, b), (a, -b), (-a, b), (-a, -b)]:
                if A * B == n and (A % 2) == (B % 2):
                    return True
            # Check also swapped pairs
            for A, B in [(b, a), (b, -a), (-b, a), (-b, -a)]:
                if A * B == n and (A % 2) == (B % 2):
                    return True
    return False



