def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # Special case: all 9's
    if all(ch == '9' for ch in s):
        return int('1' + '0'*(length-1) + '1')

    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[:-1][::-1])
        else:
            return int(left + left[::-1])

    odd = (length % 2 != 0)
    half_len = (length + 1) // 2 if odd else length // 2
    left = s[:half_len]
    pal = make_palindrome(left, odd)

    if pal > n:
        return pal

    # Increment the left half and form a new palindrome
    left_num = int(left) + 1
    left_str = str(left_num)
    # If incrementing causes length change (e.g., 999 -> 1000)
    if len(left_str) > len(left):
        # This means the palindrome length increases by 1 or 0 dependent on odd/even
        # For example, 999 -> 1001, length increases
        return int('1' + ('0' * (length - 1)) + '1')
    return make_palindrome(left_str, odd)



