def find_solution(a: int, b: int, n: int):
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else "No solution"
    if a == 0:
        if b != 0 and n % b == 0:
            return (0, n // b)
        else:
            return "No solution"
    if b == 0:
        if n % a == 0:
            x = n // a
            if x >= 0:
                return (x, 0)
        return "No solution"
    x = 0
    # To avoid infinite loop, we can set a reasonable upper bound for x.
    # But since spec does not provide domain limits, we scan until no solution found.
    # We will scan x from 0 up to a large number (e.g., abs(n)+10000) to avoid infinite loops.
    limit = max(abs(n), 10000) + 10000
    while x <= limit:
        remainder = n - a * x
        if b != 0 and remainder % b == 0:
            y = remainder // b
            return (x, y)
        x += 1
    return "No solution"



