def remove_column(nested_list, index):
    result = []
    for inner in nested_list:
        length = len(inner)
        if index >= 0:
            if length > index:
                result.append(inner[:index] + inner[index+1:])
            else:
                result.append(inner[:])
        else:
            pos_index = length + index
            if 0 <= pos_index < length:
                # Remove only if length > 1 to avoid emptying inner list on negative index removal
                if length > 1:
                    result.append(inner[:pos_index] + inner[pos_index+1:])
                else:
                    result.append(inner[:])
            else:
                result.append(inner[:])
    return result



