def check_subset(A, B):
    try:
        contains = A.__contains__
    except AttributeError:
        contains = None
    for b in B:
        if contains is not None:
            try:
                if contains(b):
                    continue
            except Exception:
                pass
        # fallback: scan A for b
        found = False
        try:
            for a in A:
                if a == b:
                    found = True
                    break
        except Exception:
            # If A is not iterable, no elements means b not found
            return False
        if not found:
            return False
    return True



