def lucky_num(n: int) -> list[int]:
    if n <= 0:
        return []
    numbers = list(range(1, 2 * n * 10))  # start with a large enough list
    idx = 1  # start sieving from second element (index 1)
    while idx < len(numbers) and len(numbers) < n * 10:
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th element starting from index step-1
        del numbers[step - 1::step]
        idx += 1
    return numbers[:n]



