def next_smallest_palindrome(num: int) -> int:
    """
    Given a non-negative integer `num`, return the smallest palindrome integer strictly greater than `num`.

    The function must handle arbitrarily large integers (beyond standard integer limits) and only accepts non-negative integers (including zero).

    A palindrome integer reads the same forwards and backwards (e.g., 121, 1331).

    Examples:
    - next_smallest_palindrome(121) -> 131
    - next_smallest_palindrome(99)  -> 101
    - next_smallest_palindrome(0)   -> 1
    """
    if num < 0:
        # Spec does not require handling negative inputs; behavior undefined
        raise ValueError("Negative inputs are not supported")

    s = str(num)
    length = len(s)

    # Special case: if num < 9, next palindrome is num+1 (single digit)
    if num < 9:
        return num + 1

    # For all 9's (e.g. 9, 99, 999), next palindrome is 10..01 (length+1 digits)
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    # Main approach:
    # 1. Create a palindrome by mirroring the left half to the right half
    # 2. If palindrome <= num, increment the middle part and mirror again

    def make_palindrome(left: str, middle: str, length: int) -> int:
        # Construct palindrome from left and middle part
        if length % 2 == 0:
            # even length: palindrome = left + reversed left
            return int(left + left[::-1])
        else:
            # odd length: palindrome = left + middle + reversed left
            return int(left + middle + left[::-1])

    half_len = length // 2
    if length % 2 == 0:
        left = s[:half_len]
        middle = ''
        palindrome = make_palindrome(left, middle, length)
        if palindrome > num:
            return palindrome
        # Increment left part
        incremented = str(int(left) + 1)
        # Handle overflow in increment (e.g. 99 -> 100)
        if len(incremented) > len(left):
            # Length increased, palindrome will be length+1 digits
            # For even length, next palindrome is 10..01 with length+1 digits
            return int('1' + ('0' * (length - 1)) + '1')
        return make_palindrome(incremented, '', length)
    else:
        left = s[:half_len]
        middle = s[half_len]
        palindrome = make_palindrome(left, middle, length)
        if palindrome > num:
            return palindrome
        # Increment middle digit + left part as one number
        left_middle_num = int(left + middle)
        incremented = str(left_middle_num + 1)
        # Handle overflow in increment (e.g. 999 -> 1000)
        if len(incremented) > len(left) + 1:
            # Length increased, palindrome length increases by 1
            return int('1' + ('0' * (length - 1)) + '1')
        # Re-split incremented into left and middle
        new_left = incremented[:-1]
        new_middle = incremented[-1]
        return make_palindrome(new_left, new_middle, length)



