def sort_sublists(collection):
    outer_type = type(collection)
    sorted_sublists = []
    for subseq in collection:
        inner_type = type(subseq)
        sorted_subseq = sorted(subseq)
        if inner_type is tuple:
            sorted_subseq = tuple(sorted_subseq)
        elif inner_type is list:
            sorted_subseq = list(sorted_subseq)
        else:
            # Preserve the original subsequence type by reconstructing with its constructor
            try:
                sorted_subseq = inner_type(sorted_subseq)
            except Exception:
                sorted_subseq = sorted_subseq  # fallback to list if reconstruction fails
        sorted_sublists.append(sorted_subseq)
    if outer_type is tuple:
        return tuple(sorted_sublists)
    elif outer_type is list:
        return sorted_sublists
    else:
        try:
            return outer_type(sorted_sublists)
        except Exception:
            return sorted_sublists



