def get_total_number_of_sequences(N: int, K: int) -> int:
    if K == 0:
        return 0
    # dp[i][x]: number of sequences of length i with last element x
    # i ranges from 1 to K
    # x ranges from 1 to N
    dp = [ [0]*(N+1) for _ in range(K+1) ]
    for x in range(1, N+1):
        dp[1][x] = 1
    for i in range(2, K+1):
        for x in range(1, N+1):
            # sum over all previous elements y with y*2 <= x
            # but per problem, a_i >= 2*a_{i-1}, so current x >= 2*previous
            # => previous y <= x//2
            limit = x//2
            s = 0
            for y in range(1, limit+1):
                s += dp[i-1][y]
            dp[i][x] = s
    return sum(dp[K][1:])



