def substract_elements(seq1, seq2):
    result = []
    outer_len = min(len(seq1), len(seq2))
    for i in range(outer_len):
        group1, group2 = seq1[i], seq2[i]
        inner_len = min(len(group1), len(group2))
        new_group = []
        for j in range(inner_len):
            elem1, elem2 = group1[j], group2[j]
            # If elements are numbers, subtract directly
            # If elements are tuples, subtract element-wise up to shortest length
            if isinstance(elem1, tuple) and isinstance(elem2, tuple):
                elem_len = min(len(elem1), len(elem2))
                new_elem = tuple(elem1[k] - elem2[k] for k in range(elem_len))
            else:
                new_elem = elem1 - elem2
            new_group.append(new_elem)
        result.append(tuple(new_group))
    return tuple(result)



