def lucky_num(n: int) -> list[int]:
    if n <= 0:
        return []
    numbers = list(range(1, 2 * n * n))  # initial large list to ensure enough lucky numbers
    idx = 1  # start from second element (index 1) which is step
    while idx < len(numbers) and len(numbers) < n:
        step = numbers[idx]
        if step > len(numbers):
            break
        # remove every step-th number (1-based index)
        numbers = [num for i, num in enumerate(numbers, 1) if i % step != 0]
        idx += 1
    return numbers[:n]



