def dif_Square(n: int) -> bool:
    # n = a^2 - b^2 = (a-b)(a+b)
    # Let x = a-b and y = a+b, both integers.
    # Then n = x*y, and a = (x+y)/2, b = (y - x)/2 must be integers.
    # So (x + y) and (y - x) must both be even => x and y have same parity.
    # Thus, n can be expressed as a difference of squares iff n has a factorization n = x*y
    # with x,y integers of same parity.

    # Iterate over divisors x of n (both positive and negative)
    # For each x, y = n//x if x divides n
    # Check if x and y have same parity
    if n == 0:
        # 0 = 0^2 - 0^2 trivially
        return True
    from math import isqrt

    abs_n = abs(n)
    # To cover negative n, consider divisors of abs_n with sign combinations

    # We'll iterate from 1 to isqrt(abs_n)
    for x in range(1, isqrt(abs_n) + 1):
        if abs_n % x == 0:
            y = abs_n // x
            # Check four sign combinations because n can be negative:
            # x,y both positive => x*y = abs_n, check parity and sign
            # For n > 0: x*y = n, so sign(x)*sign(y)=1
            # For n < 0: x*y = -abs_n, so sign(x)*sign(y) = -1
            candidates = [(x, y), (-x, -y), (x, -y), (-x, y)]
            for a, b in candidates:
                if a * b == n:
                    # Check parity
                    if (a % 2) == (b % 2):
                        # then a,b have same parity => (a+b)/2 and (b - a)/2 integers
                        return True
    return False



