def zip_tuples(t1: tuple, t2: tuple) -> tuple:
    """
    Takes two tuples, t1 and t2, and returns a tuple of pairs where each pair consists of elements from t1 and t2 at the corresponding positions.
    If t2 is shorter than t1, elements from t2 are repeated cyclically until all elements of t1 have been paired.
    The length of the returned tuple is always equal to the length of t1.

    Parameters:
    t1 (tuple): The first tuple.
    t2 (tuple): The second tuple.

    Returns:
    tuple: A tuple of pairs, each pair containing one element from t1 and one element from t2.
    """
    if not t2:
        # If t2 is empty, cycling is impossible; to avoid ZeroDivisionError, raise error
        raise ValueError("Second tuple must not be empty for cycling")
    return tuple((t1[i], t2[i % len(t2)]) for i in range(len(t1)))



