def next_smallest_palindrome(n: int) -> int:
    # Handle edge cases for small n
    if n <= 0:
        # No palindrome less than 0 in nonnegative integers
        # Spec does not forbid negative or zero input, so return -1 to indicate no valid palindrome
        return -1
    if 1 <= n <= 10:
        return n - 1  # single-digit palindromes descend by 1

    s = str(n)
    length = len(s)

    # Helper to check palindrome
    def is_palindrome(x: int) -> bool:
        sx = str(x)
        return sx == sx[::-1]

    # Construct palindrome from left half
    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[-2::-1])
        else:
            return int(left + left[::-1])

    half_len = (length + 1) // 2
    left_part = s[:half_len]

    # First candidate palindrome by mirroring left part
    candidate = make_palindrome(left_part, length % 2 == 1)

    if candidate >= n:
        # Need to decrement the left part and rebuild palindrome
        left_num = int(left_part)
        left_num -= 1
        left_str = str(left_num)
        # If decrement causes length change, handle separately (e.g. 1000 -> 999)
        if len(left_str) < len(left_part):
            # Means length reduced, so palindrome is all 9s of length-1
            return int("9" * (length - 1))
        candidate = make_palindrome(left_str, length % 2 == 1)

    if candidate < n:
        return candidate

    # If candidate is still not less than n (should not happen), fallback
    # Return largest palindrome less than n by scanning downwards (slow fallback)
    # This fallback is safe but slow, used for completeness
    for x in range(n - 1, -1, -1):
        if is_palindrome(x):
            return x

    # If no palindrome found (theoretically impossible), return -1
    return -1



