def find_solution(a: int, b: int, n: int):
    if n < 0:
        return None
    max_x = n // a if a > 0 else 0
    for x in range(max_x + 1):
        remainder = n - a * x
        if remainder < 0:
            break
        if b != 0 and remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)
        elif b == 0:
            # If b == 0, then ax = n, so remainder must be 0 and y can be 0
            if remainder == 0:
                return (x, 0)
    return None



