def find_exponentio(bases: tuple[int, ...], exps: tuple[int, ...]) -> tuple[int, ...]:
    if not (isinstance(bases, tuple) and isinstance(exps, tuple)):
        raise TypeError("Both arguments must be tuples.")
    if len(bases) != len(exps):
        raise ValueError(f"Length mismatch: bases has length {len(bases)}, exps has length {len(exps)}")
    if not all(isinstance(b, int) for b in bases):
        raise TypeError("All elements in bases must be integers.")
    if not all(isinstance(e, int) for e in exps):
        raise TypeError("All elements in exps must be integers.")
    result = tuple(b ** e for b, e in zip(bases, exps))
    # Ensure all results are ints, cover cases like negative exponents producing floats
    if not all(isinstance(r, int) for r in result):
        # If any result is float, raise error as it violates int element output requirement
        raise ValueError("Exponentiation result contains non-integer values.")
    return result



