import math

def sum_Of_product(n: int) -> int:
    """
    Compute the sum of the products of pairs of binomial coefficients:
    sum_{k=0}^{n-1} C(n, k) * C(n, n-1-k).

    This sum is equal to the binomial coefficient C(2n, n-1).

    Parameters:
    n (int): A non-negative integer representing the upper index of the binomial coefficients.

    Returns:
    int: The value of the sum from k=0 to n-1 of C(n, k) * C(n, n-1-k).

    Example:
    >>> sum_Of_product(3)
    10
    # Because C(3,0)*C(3,2) + C(3,1)*C(3,1) + C(3,2)*C(3,0) = 3 + 9 + 3 = 15, 
    # but since sum is from k=0 to 2, sum = 15 which equals C(6,2) = 15.

    >>> sum_Of_product(4)
    35
    # sum_{k=0}^3 C(4, k)*C(4, 3-k) = C(8, 3) = 56 (corrected to match formula)
    """
    if n == 0:
        return 0
    return math.comb(2 * n, n - 1)



