def move_num(s1: str, s2: str) -> str:
    digits_in_s2 = {ch for ch in s2 if ch.isdigit()}
    if not digits_in_s2:
        digits_in_s2 = set('0123456789')
    moved_digits = [ch for ch in s1 if ch in digits_in_s2]
    filtered_s1 = ''.join(ch for ch in s1 if ch not in digits_in_s2)
    return filtered_s1 + s2 + ''.join(moved_digits)



