def get_noOfways(n: int) -> int:
    """
    Calculate the number of ways to completely tile a 2 x n board using 2 x 1 domino tiles.

    Parameters:
    n (int): The length of the board.

    Returns:
    int: The total number of distinct ways to tile the 2 x n board using 2 x 1 dominoes placed either vertically or horizontally.

    Notes:
    - Only 2 x 1 domino tiles are used.
    - Dominoes can be placed vertically or horizontally.
    - The board must be fully covered without overlaps or gaps.

    Examples:
    >>> get_noOfways(1)
    1
    >>> get_noOfways(2)
    2
    >>> get_noOfways(3)
    3
    """
    if n == 1:
        return 1
    elif n == 2:
        return 2
    a, b = 1, 2
    for _ in range(3, n + 1):
        a, b = b, a + b
    return b



