def digits(n):
    """
    Given a positive integer n, return the product of its odd digits.
    If n contains no odd digits, return 0.

    Examples:
    digits(1) == 1        # only odd digit is 1, product is 1
    digits(4) == 0        # no odd digits, return 0
    digits(235) == 15     # odd digits are 3 and 5, product is 3 * 5 = 15
    """
    product = 1
    found_odd = False
    while n > 0:
        d = n % 10
        if d % 2 == 1:
            product *= d
            found_odd = True
        n //= 10
    return product if found_odd else 0



