from typing import List, Tuple

def parse_music(music_string: str) -> Tuple[List[int], str]:
    # Fixed mapping of beats for recognized notes
    beat_map = {'o': 4, 'o|': 2, '.|': 1}

    # Split tokens (O(1) as per spec - assume fixed format or constant max tokens)
    tokens = music_string.split()

    # Map tokens to beats or keep unknown tokens as strings
    beats = [beat_map[t] if t in beat_map else t for t in tokens]

    # Count frequencies of recognized notes only
    freq = {'o': 0, 'o|': 0, '.|': 0}
    for t in tokens:
        if t in freq:
            freq[t] += 1

    # Find max frequency
    max_freq = max(freq.values())
    # Candidates with max frequency
    candidates = [note for note, count in freq.items() if count == max_freq and count > 0]
    if not candidates:
        # No recognized notes present, return empty list and empty string
        return beats, ''

    # Tie breaker: pick note with longest beat length among candidates
    max_beat = -1
    common_note = ''
    for note in candidates:
        if beat_map[note] > max_beat:
            max_beat = beat_map[note]
            common_note = note

    return beats, common_note



