def monotonic(l):
    if not isinstance(l, (list, str)):
        raise TypeError
    if isinstance(l, list):
        # Empty list is monotonic, sum=0
        if len(l) == 0:
            return True, 0
        def non_decreasing(i=1):
            if i == len(l):
                return True
            if l[i] < l[i-1]:
                return False
            return non_decreasing(i+1)
        def non_increasing(i=1):
            if i == len(l):
                return True
            if l[i] > l[i-1]:
                return False
            return non_increasing(i+1)
        if non_decreasing() or non_increasing():
            return True, int(sum(l))
        return False
    else:
        # string case
        # Empty string is strictly monotonic trivially
        if len(l) == 0:
            return True, ""
        def strictly_increasing(i=1):
            if i == len(l):
                return True
            if l[i] <= l[i-1]:
                return False
            return strictly_increasing(i+1)
        def strictly_decreasing(i=1):
            if i == len(l):
                return True
            if l[i] >= l[i-1]:
                return False
            return strictly_decreasing(i+1)
        # Check duplicates by length equality with set
        if len(set(l)) != len(l):
            return False
        if strictly_increasing() or strictly_decreasing():
            return True, l
        return False



