def maximum(arr, k):
    """
    Given an array arr of integers (or strings) and a non-negative integer k, return a sorted list 
    of length k containing the maximum k elements from arr. The returned list must be sorted in ascending order.

    Notes:
        - The input array arr can contain integers or strings.
        - If k is 0, return an empty list.
        - The length of arr is between 1 and 1000 inclusive.
        - Elements in arr are within the range [-1000, 1000] for integers; strings can be any valid string.
        - You must not use any built-in sorting functions.
        - The time complexity requirement is disregarded; a realistic complexity such as O(n) or O(n log k) is acceptable.

    Examples:

        Input: arr = [-3, -4, 5], k = 3
        Output: [-4, -3, 5]

        Input: arr = [4, -4, 4], k = 2
        Output: [4, 4]

        Input: arr = [-3, 2, 1, 2, -1, -2, 1], k = 1
        Output: [2]
    """
    if k == 0:
        return []

    # Find the k largest elements using a selection algorithm (Quickselect variant)
    def partition(nums, left, right, pivot_index):
        pivot_value = nums[pivot_index]
        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]
        store_index = left
        for i in range(left, right):
            if nums[i] < pivot_value:
                nums[store_index], nums[i] = nums[i], nums[store_index]
                store_index += 1
        nums[right], nums[store_index] = nums[store_index], nums[right]
        return store_index

    def select(nums, left, right, k_smallest):
        while True:
            if left == right:
                return
            pivot_index = left + (right - left) // 2
            pivot_index = partition(nums, left, right, pivot_index)
            if k_smallest == pivot_index:
                return
            elif k_smallest < pivot_index:
                right = pivot_index - 1
            else:
                left = pivot_index + 1

    n = len(arr)
    nums = arr[:]  # copy to avoid modifying input

    # k largest means we want to find the (n-k)-th smallest element as pivot
    select(nums, 0, n - 1, n - k)

    # nums[n-k:] contains the k largest elements but unordered
    result = nums[n - k:]

    # Implement insertion sort (or any simple sort) since k <= n and n <= 1000
    for i in range(1, k):
        key = result[i]
        j = i - 1
        while j >= 0 and result[j] > key:
            result[j + 1] = result[j]
            j -= 1
        result[j + 1] = key

    return result



