def sum_squares(lst):
    def transform(i):
        if i % 3 == 0:
            return lst[i] ** 2
        elif i % 2 == 0:
            return lst[i] ** 3
        else:
            return lst[i]
    s = 0
    if len(lst) > 0:
        s += transform(0)
    if len(lst) > 2:
        s += transform(2)
    if len(lst) > 3:
        s += transform(3)
    return str(s)



