def sort_even(l: list):
    even_indices = list(range(0, len(l), 2))
    even_vals = [l[i] for i in even_indices]
    even_vals_sorted = sorted(even_vals)
    # Enforce strict ascending order by adjusting duplicates minimally without removing elements
    for i in range(1, len(even_vals_sorted)):
        if even_vals_sorted[i] <= even_vals_sorted[i-1]:
            even_vals_sorted[i] = even_vals_sorted[i-1] + 1e-12
    result = l[:]
    for idx, val in zip(even_indices, even_vals_sorted):
        result[idx] = val
    return result



