def move_one_ball(arr):
    if not arr:
        return True
    n = len(arr)
    # Check if arr is strictly increasing
    def is_strictly_increasing(a):
        return all(a[i] < a[i+1] for i in range(len(a)-1))
    if is_strictly_increasing(arr):
        return True
    # Try all right shifts from 1 to n-1
    for shift in range(1, n):
        rotated = arr[-shift:] + arr[:-shift]
        if is_strictly_increasing(rotated):
            return True
    return False



