def maximum(arr, k):
    if k == 0:
        return []
    sorted_arr = sorted(arr, reverse=True)
    kth_largest = sorted_arr[k-1]
    filtered = [x for x in arr if x > kth_largest]
    count_needed = k - len(filtered)
    # Add exactly count_needed of kth_largest (any subset)
    filtered += [kth_largest] * count_needed
    return sorted(filtered)



