def triples_sum_to_zero(items):
    """
    triples_sum_to_zero accepts a collection of values.
    It returns True if there exist three distinct elements at different indices in the collection
    whose values sum to zero, and False otherwise.

    The three elements must be at distinct indices, but they may have the same value.
    For example, triples_sum_to_zero([0, 0, 0]) returns True because the three zeros at distinct indices sum to zero.
    Using the same element multiple times at the same index is not allowed.

    Examples:

    >>> triples_sum_to_zero([1, 3, 5, 0])
    False
    >>> triples_sum_to_zero([1, 3, -2, 1])
    True
    >>> triples_sum_to_zero([1, 2, 3, 7])
    False
    >>> triples_sum_to_zero([2, 4, -5, 3, 9, 7])
    True
    >>> triples_sum_to_zero([1])
    False
    """
    n = len(items)
    if n < 3:
        return False
    items_sorted = sorted(items)
    for i in range(n - 2):
        a = items_sorted[i]
        left = i + 1
        right = n - 1
        while left < right:
            total = a + items_sorted[left] + items_sorted[right]
            if total == 0:
                return True
            elif total < 0:
                left += 1
            else:
                right -= 1
    return False



