def monotonic(seq):
    """
    Return True if the sequence is monotonic, that is, entirely nondecreasing or entirely nonincreasing,
    allowing equality between adjacent elements. The sequence must not contain any fluctuations 
    where the direction reverses.

    In other words, monotonic returns True if for all adjacent pairs (seq[i], seq[i+1]):
    - seq[i] <= seq[i+1] for all i (nondecreasing), or
    - seq[i] >= seq[i+1] for all i (nonincreasing).

    Examples:
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    >>> monotonic([1, 1, 2, 2])
    True
    >>> monotonic([1, 3, 2, 4])
    False
    """
    if len(seq) < 2:
        return True
    nondecreasing = all(x <= y for x, y in zip(seq, seq[1:]))
    nonincreasing = all(x >= y for x, y in zip(seq, seq[1:]))
    return nondecreasing or nonincreasing



