def smallest_change(arr):
    """
    Given an array arr of integers, determine the minimal number of element changes required to make the array palindromic.
    A palindromic array reads the same forwards and backwards.
    In one change, you can change a single element to any integer value.

    The minimal number of changes equals the count of mismatched element pairs at symmetric positions in the array.
    Each mismatched pair requires exactly one change to fix (changing either element), and no further optimization by global reassignment is needed.

    Parameters:
    arr (List[int]): The input array of integers.

    Returns:
    int: The minimal number of changes required to make arr palindromic.

    Examples:
    >>> smallest_change([1, 2, 3, 2, 1])
    0
    >>> smallest_change([1, 2, 3, 4, 1])
    1
    >>> smallest_change([1, 2, 3, 4, 5])
    2
    """
    n = len(arr)
    count = 0
    for i in range(n // 2):
        if arr[i] != arr[n - 1 - i]:
            count += 1
    return count



