def prime_length(string):
    """
    Return True if the input string contains at least one palindrome substring of length two or more; otherwise, return False.

    A palindrome substring is a contiguous sequence of characters within the string that reads the same forwards and backwards.

    Examples:
    prime_length('Hello') == True      # 'll' is a palindrome substring
    prime_length('abcdcba') == True    # 'abcdcba' itself is a palindrome substring
    prime_length('kittens') == True    # 'tt' is a palindrome substring
    prime_length('orange') == False    # no palindrome substring of length ≥ 2
    """
    n = len(string)
    if n < 2:
        return False

    for i in range(n):
        # check even length palindromes centered between i and i+1
        left, right = i, i + 1
        while left >= 0 and right < n and string[left] == string[right]:
            if right - left + 1 >= 2:
                return True
            left -= 1
            right += 1

        # check odd length palindromes centered at i
        left, right = i - 1, i + 1
        while left >= 0 and right < n and string[left] == string[right]:
            if right - left + 1 >= 2:
                return True
            left -= 1
            right += 1

    return False



