from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    """
    Given an input string consisting of multiple groups of balanced nested parentheses separated by spaces,
    return a list of integers representing the maximum depth of nesting in each group.

    Each group is assumed to contain only balanced parentheses; the function does not need to validate balance
    or handle unbalanced groups.

    For example, the group "(()())" has a maximum nesting depth of 2, while "((()))" has a maximum nesting depth of 3.

    Examples:
    >>> parse_nested_parens('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]
    """
    if not paren_string.strip():
        return []
    groups = paren_string.split()
    depths = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
        depths.append(max_depth)
    return depths



