def parse_music(notes: str) -> list[int]:
    """
    Parse a string representing musical notes and return a list of integers corresponding to how many beats each note lasts.

    The input string consists of the following note patterns:
    - 'o|'  : half note, lasts 2 beats
    - 'o'   : whole note, lasts 4 beats
    - '.|'  : quarter note, lasts 1 beat

    The parser should greedily match the longest valid note pattern at each position. For example, it matches 'o|' instead of 'o' when possible.

    If the input string contains any invalid or unrecognized characters or sequences (i.e., anything that does not match one of the three valid note patterns), the function should raise an error or reject the input rather than attempting partial parsing.

    Returns:
        A list of integers corresponding exactly to the beat lengths of the matched notes in order.
    """
    result = []
    i = 0
    length = len(notes)
    while i < length:
        # Try to match the longest pattern first
        if i + 2 <= length and notes[i:i+2] == 'o|':
            result.append(2)
            i += 2
        elif i + 2 <= length and notes[i:i+2] == '.|':
            result.append(1)
            i += 2
        elif notes[i] == 'o':
            result.append(4)
            i += 1
        else:
            raise ValueError(f"Invalid note pattern at position {i}: {notes[i:]}")
    return result



