def decode_shift(s):
    """
    Takes as input a string encoded with the encode_shift function, which shifts each lowercase letter 'a'–'z' forward by 5 positions in the alphabet, wrapping around from 'z' to 'a'. Returns the decoded string by shifting each lowercase letter 'a'–'z' backward by 5 positions, wrapping around from 'a' to 'z'. All characters that are not lowercase letters 'a'–'z' remain unchanged in the output.
