def monotonic(lst):
    """
    Return True if the elements in the input list are monotonic, i.e., either monotonically non-decreasing or monotonically non-increasing.

    A list is considered monotonically non-decreasing if for every pair of consecutive elements, the latter is greater than or equal to the former.
    Similarly, a list is considered monotonically non-increasing if for every pair of consecutive elements, the latter is less than or equal to the former.

    Parameters:
        lst (list): A list of comparable elements.

    Returns:
        bool: True if the list is monotonic (non-decreasing or non-increasing), False otherwise.

    Examples:
        monotonic([1, 2, 2, 3])  # True
        monotonic([3, 2, 2, 1])  # True
        monotonic([1, 3, 2])     # False
        monotonic([5])           # True
        monotonic([])            # True
    """
    if len(lst) <= 1:
        return True
    non_decreasing = True
    non_increasing = True
    for i in range(1, len(lst)):
        if lst[i] < lst[i - 1]:
            non_decreasing = False
        if lst[i] > lst[i - 1]:
            non_increasing = False
        if not non_decreasing and not non_increasing:
            return False
    return True



