def monotonic(numbers):
    """
    Determine whether the given list of numbers is monotonic.

    A list is considered monotonic if it is either entirely non-decreasing
    (each element is greater than or equal to the previous one) or entirely
    non-increasing (each element is less than or equal to the previous one).

    Parameters:
    numbers (list of numbers): The list of numbers to check.

    Returns:
    bool: True if the list is monotonic (non-decreasing or non-increasing), False otherwise.

    Examples:
    >>> monotonic([1, 2, 2, 3])
    True
    >>> monotonic([6, 5, 5, 4])
    True
    >>> monotonic([1, 3, 2])
    False
    >>> monotonic([1])
    True
    >>> monotonic([])
    True
    """
    if len(numbers) <= 1:
        return True
    non_decreasing = all(numbers[i] >= numbers[i-1] for i in range(1, len(numbers)))
    non_increasing = all(numbers[i] <= numbers[i-1] for i in range(1, len(numbers)))
    return non_decreasing or non_increasing



