def decode_shift(s: str):
    """
    Takes as input a string encoded with the encode_shift function. Returns the decoded string by shifting every lowercase letter by -5 positions in the alphabet, wrapping around from 'a' to 'z' as needed. All characters that are not lowercase letters ('a'–'z') are left unchanged.
    """
    result = []
    for c in s:
