def monotonic(l: list):
    """
    Return True if the list elements are monotonic, i.e., if they are either monotonically non-decreasing
    (each element is greater than or equal to the previous) or monotonically non-increasing 
    (each element is less than or equal to the previous).

    Examples:
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    """
    if len(l) < 2:
        return True
    non_decreasing = all(l[i] <= l[i+1] for i in range(len(l)-1))
    non_increasing = all(l[i] >= l[i+1] for i in range(len(l)-1))
    return non_decreasing or non_increasing



