def maximum(arr, k):
    if k == 0:
        return []
    sorted_arr = sorted(arr)
    kth_largest = sorted_arr[-k]
    result = []
    count_needed = k
    # Traverse from the end (largest to smallest)
    for x in reversed(sorted_arr):
        if x > kth_largest:
            result.append(x)
            count_needed -= 1
        elif x == kth_largest and count_needed > 0:
            result.append(x)
            count_needed -= 1
        if count_needed == 0:
            break
    return sorted(result)



