import math

def sum_squares(lst):
    """
    Given a list of numbers (which may include integers, floats, and negatives), 
    return the sum of the squares of the ceiling of each number in the list.

    To compute this:
    - Apply the ceiling function to each number in the list (round each number up to the nearest integer).
    - Square the resulting integer.
    - Sum all these squared values and return the total.

    Examples:
    For lst = [1, 2, 3] the output should be 14
    For lst = [1, 4, 9] the output should be 98
    For lst = [1, 3, 5, 7] the output should be 84
    For lst = [1.4, 4.2, 0] the output should be 29
    For lst = [-2.4, 1, 1] the output should be 6
    """
