def search(lst):
    '''
    Given a non-empty list of positive integers, return the smallest integer in the list 
    whose frequency (the number of times it appears in the list) is greater than or equal 
    to its own value. If no such integer exists, return -1.

    Parameters:
    lst (list of int): A non-empty list of positive integers.

    Returns:
    int: The smallest integer whose frequency is at least its value, or -1 if none exists.

    Examples:
    search([4, 1, 2, 2, 3, 1]) == 4
    search([1, 2, 2, 3, 3, 3, 4, 4, 4]) == 4
    search([5, 5, 4, 4, 4]) == 5
    '''
    from collections import Counter
    freq = Counter(lst)
    candidates = [x for x in freq if freq[x] >= x]
    return min(candidates) if candidates else -1



